// ChargingSchedulePeriod: Charging schedule period structure defines a time period in a charging
// schedule. It is used in: CompositeScheduleType and in ChargingScheduleType. When used in a
// NotifyEVChargingScheduleRequest only _startPeriod_, _limit_, _limit_L2_, _limit_L3_ are relevant.
type ChargingSchedulePeriod struct {
	// StartPeriod: Start of the period, in seconds from the start of schedule. The value of
	// StartPeriod also defines the stop time of the previous period.
	StartPeriod int `json:"startPeriod" ocpp:"required"`
	// Limit: Optional only when not required by the _operationMode_, as in CentralSetpoint,
	// ExternalSetpoint, ExternalLimits, LocalFrequency, LocalLoadBalancing. + Charging rate limit
	// during the schedule period, in the applicable _chargingRateUnit_. This SHOULD be a non-negative
	// value; a negative value is only supported for backwards compatibility with older systems that
	// use a negative value to specify a discharging limit. When using _chargingRateUnit_ = `W`, this
	// field represents the sum of the power of all phases, unless values are provided for L2 and L3,
	// in which case this field represents phase L1.
	Limit *float64 `json:"limit,omitempty"`
	// LimitL2: *(2.1)* Charging rate limit on phase L2 in the applicable _chargingRateUnit_.
	LimitL2 *float64 `json:"limit_L2,omitempty"`
	// LimitL3: *(2.1)* Charging rate limit on phase L3 in the applicable _chargingRateUnit_.
	LimitL3 *float64 `json:"limit_L3,omitempty"`
	// NumberPhases is the number of phases that can be used for charging. + For a DC EVSE this field
	// should be omitted. + For an AC EVSE a default value of _numberPhases_ = 3 will be assumed if the
	// field is absent.
	NumberPhases *int `json:"numberPhases,omitempty"`
	// PhaseToUse: Values: 1..3, Used if numberPhases=1 and if the EVSE is capable of switching the
	// phase connected to the EV, i.e. ACPhaseSwitchingSupported is defined and true. It’s not
	// allowed unless both conditions above are true. If both conditions are true, and phaseToUse is
	// omitted, the Charging Station / EVSE will make the selection on its own.
	PhaseToUse *int `json:"phaseToUse,omitempty"`
	// DischargeLimit: *(2.1)* Limit in _chargingRateUnit_ that the EV is allowed to discharge with.
	// Note, these are negative values in order to be consistent with _setpoint_, which can be positive
	// and negative. + For AC this field represents the sum of all phases, unless values are provided
	// for L2 and L3, in which case this field represents phase L1.
	DischargeLimit *float64 `json:"dischargeLimit,omitempty"`
	// DischargeLimitL2: *(2.1)* Limit in _chargingRateUnit_ on phase L2 that the EV is allowed to
	// discharge with.
	DischargeLimitL2 *float64 `json:"dischargeLimit_L2,omitempty"`
	// DischargeLimitL3: *(2.1)* Limit in _chargingRateUnit_ on phase L3 that the EV is allowed to
	// discharge with.
	DischargeLimitL3 *float64 `json:"dischargeLimit_L3,omitempty"`
	// Setpoint: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow as close as possible.
	// Use negative values for discharging. + When a limit and/or _dischargeLimit_ are given the
	// overshoot when following _setpoint_ must remain within these values. This field represents the
	// sum of all phases, unless values are provided for L2 and L3, in which case this field represents
	// phase L1.
	Setpoint *float64 `json:"setpoint,omitempty"`
	// SetpointL2: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow on phase L2 as
	// close as possible.
	SetpointL2 *float64 `json:"setpoint_L2,omitempty"`
	// SetpointL3: *(2.1)* Setpoint in _chargingRateUnit_ that the EV should follow on phase L3 as
	// close as possible.
	SetpointL3 *float64 `json:"setpoint_L3,omitempty"`
	// SetpointReactive: *(2.1)* Setpoint for reactive power (or current) in _chargingRateUnit_ that
	// the EV should follow as closely as possible. Positive values for inductive, negative for
	// capacitive reactive power or current. + This field represents the sum of all phases, unless
	// values are provided for L2 and L3, in which case this field represents phase L1.
	SetpointReactive *float64 `json:"setpointReactive,omitempty"`
	// SetpointReactiveL2: *(2.1)* Setpoint for reactive power (or current) in _chargingRateUnit_ that
	// the EV should follow on phase L2 as closely as possible.
	SetpointReactiveL2 *float64 `json:"setpointReactive_L2,omitempty"`
	// SetpointReactiveL3: *(2.1)* Setpoint for reactive power (or current) in _chargingRateUnit_ that
	// the EV should follow on phase L3 as closely as possible.
	SetpointReactiveL3 *float64 `json:"setpointReactive_L3,omitempty"`
	// PreconditioningRequest: *(2.1)* If true, the EV should attempt to keep the BMS preconditioned
	// for this time interval.
	PreconditioningRequest *bool `json:"preconditioningRequest,omitempty"`
	// EVSESleep: *(2.1)* If true, the EVSE must turn off power electronics/modules associated with
	// this transaction. Default value when absent is false.
	EVSESleep *bool `json:"evseSleep,omitempty"`
	// V2XBaseline: *(2.1)* Power value that, when present, is used as a baseline on top of which
	// values from _v2xFreqWattCurve_ and _v2xSignalWattCurve_ are added.
	V2XBaseline *float64 `json:"v2xBaseline,omitempty"`
	// OperationMode is the operationMode field.
	OperationMode OperationMode `json:"operationMode,omitempty"`
	// V2XFreqWattCurve is the v2xFreqWattCurve field.
	V2XFreqWattCurve []V2XFreqWattPoint `json:"v2xFreqWattCurve,omitempty"`
	// V2XSignalWattCurve is the v2xSignalWattCurve field.
	V2XSignalWattCurve []V2XSignalWattPoint `json:"v2xSignalWattCurve,omitempty"`
	// CustomData holds vendor-specific extension data.
	CustomData *CustomData `json:"customData,omitempty"`
}

