// ChargingSchedule: Charging schedule structure defines a list of charging periods, as used in:
// NotifyEVChargingScheduleRequest and ChargingProfileType. When used in a
// NotifyEVChargingScheduleRequest only _duration_ and _chargingSchedulePeriod_ are relevant and
// _chargingRateUnit_ must be 'W'. + An ISO 15118-20 session may provide either an
// _absolutePriceSchedule_ or a _priceLevelSchedule_. An ISO 15118-2 session can only provide
// a_salesTariff_ element. The field _digestValue_ is used when price schedule or sales tariff are
// signed. image::images/ChargingSchedule-Simple.png[]
type ChargingSchedule struct {
	// ID is the id field.
	ID int `json:"id" ocpp:"required"`
	// LimitAtSoC is the limitAtSoC field.
	LimitAtSoC *LimitAtSoC `json:"limitAtSoC,omitempty"`
	// StartSchedule: Starting point of an absolute schedule or recurring schedule.
	StartSchedule *ocpp.DateTime `json:"startSchedule,omitempty"`
	// Duration of the charging schedule in seconds. If the duration is left empty, the last period
	// will continue indefinitely or until end of the transaction in case startSchedule is absent.
	Duration *int `json:"duration,omitempty"`
	// ChargingRateUnit is the chargingRateUnit field.
	ChargingRateUnit ChargingRateUnit `json:"chargingRateUnit" ocpp:"required"`
	// MinChargingRate: Minimum charging rate supported by the EV. The unit of measure is defined by
	// the chargingRateUnit. This parameter is intended to be used by a local smart charging algorithm
	// to optimize the power allocation for in the case a charging process is inefficient at lower
	// charging rates.
	MinChargingRate *float64 `json:"minChargingRate,omitempty"`
	// PowerTolerance: *(2.1)* Power tolerance when following EVPowerProfile.
	PowerTolerance *float64 `json:"powerTolerance,omitempty"`
	// SignatureID: *(2.1)* Id of this element for referencing in a signature.
	SignatureID *int `json:"signatureId,omitempty"`
	// DigestValue: *(2.1)* Base64 encoded hash (SHA256 for ISO 15118-2, SHA512 for ISO 15118-20) of
	// the EXI price schedule element. Used in signature.
	DigestValue string `json:"digestValue,omitempty"`
	// UseLocalTime: *(2.1)* Defaults to false. When true, disregard time zone offset in dateTime
	// fields of _ChargingScheduleType_ and use unqualified local time at Charging Station instead.
	// This allows the same `Absolute` or `Recurring` charging profile to be used in both summer and
	// winter time.
	UseLocalTime *bool `json:"useLocalTime,omitempty"`
	// ChargingSchedulePeriod is the chargingSchedulePeriod field.
	ChargingSchedulePeriod []ChargingSchedulePeriod `json:"chargingSchedulePeriod,omitempty" ocpp:"required"`
	// RandomizedDelay: *(2.1)* Defaults to 0. When _randomizedDelay_ not equals zero, then the start
	// of each ChargingSchedulePeriodType is delayed by a randomly chosen number of seconds between 0
	// and _randomizedDelay_. Only allowed for TxProfile and TxDefaultProfile.
	RandomizedDelay *int `json:"randomizedDelay,omitempty"`
	// SalesTariff is the salesTariff field.
	SalesTariff *SalesTariff `json:"salesTariff,omitempty"`
	// AbsolutePriceSchedule is the absolutePriceSchedule field.
	AbsolutePriceSchedule *AbsolutePriceSchedule `json:"absolutePriceSchedule,omitempty"`
	// PriceLevelSchedule is the priceLevelSchedule field.
	PriceLevelSchedule *PriceLevelSchedule `json:"priceLevelSchedule,omitempty"`
	// CustomData holds vendor-specific extension data.
	CustomData *CustomData `json:"customData,omitempty"`
}

